// Extract, Parse, and Reconstruct the Master Agent JSON Output
// PII tokens will be swapped back here.
const llmOut = $input.first().json.output || $input.first().json.text || '{}';
const context = $('Prepare Agent Context').first().json;
const tokenMap = context.token_map || {};

let parsed = {};
try {
  parsed = JSON.parse(llmOut.replace(/```json|```/g, '').trim());
} catch(e) {
  parsed = {
    legal_analysis: 'Parse Error - Master JSON corrupted',
    draft_document: { document_title: 'Draft Error', body: 'The AI output could not be parsed.' },
    research_brief: { findings: 'N/A' },
    crm_outputs: { email_body: 'Error', linkedin_post: 'Error' },
    instructions_to_lawyer: ['Manual intervention required.']
  };
}

// PII Swap function
const restorePii = (text) => {
  if (!text) return '';
  let out = text;
  for (const [token, realName] of Object.entries(tokenMap)) {
    out = out.split(token).join(realName);
  }
  return out;
};

// Rebuild text with restored PII
const finalDraftBody = restorePii(parsed.draft_document?.body);
const finalResearch = restorePii(parsed.research_brief?.findings);
const finalEmail = restorePii(parsed.crm_outputs?.email_body);

// Construct the Mega-Document Text to push to Google Docs
const megaDoc = `*** DRAFT — SUBJECT TO LAWYER REVIEW ***\n\n` +
  `--- 1. LEGAL OPINION & STRATEGY ---\n${parsed.legal_analysis}\n\n` +
  `--- 2. RESEARCH FINDINGS ---\nAuthorities: ${(parsed.research_brief?.statutes || []).join(', ')} | ${(parsed.research_brief?.cases || []).join(', ')}\n${finalResearch}\n\n` +
  `--- 3. MASTER LEGAL DRAFT ---\nTitle: ${parsed.draft_document?.document_title}\n\n${finalDraftBody}\n\n` +
  `--- 4. CLIENT COMMUNICATIONS (CRM) ---\nSubject: ${parsed.crm_outputs?.email_subject}\nEmail Body:\n${finalEmail}\n\n` +
  `LinkedIn Post:\n${parsed.crm_outputs?.linkedin_post}`;

return [{
  json: {
    ...context,
    master_agent_output: parsed,
    mega_doc_text: megaDoc,
    mega_doc_title: '[MASTER DRAFT] ' + (parsed.draft_document?.document_title || context.matter_id),
    matter_id: context.matter_id,
    timestamp: new Date().toISOString(),
    instructions: parsed.instructions_to_lawyer || []
  }
}];

const docJson = $input.first().json;
const masterCtx = $('Parse Output & Restore PII').first().json;

const fileId = docJson.id || docJson.documentId;
const driveUrl = docJson.documentUrl || (fileId ? `https://docs.google.com/document/d/${fileId}/edit` : '');

const agent_output = {
  agent: 'master_agent',
  output_type: 'unified_matter_pack',
  document_title: masterCtx.mega_doc_title,
  drive_url: driveUrl,
  file_id: fileId,
  matter_id: masterCtx.matter_id,
  channel: masterCtx.channel,
  sender: masterCtx.sender,
  instructions_to_lawyer: masterCtx.instructions,
  timestamp: masterCtx.timestamp,
  requires_approval: true
};

return [{
  json: {
    ...masterCtx,
    agent_output
  }
}];
